def t7_tax_annual(legacy_dir) -> dict[tuple[str, int], tuple[Decimal, ...]]:
    """{(policy_id, year): (ch_stp, ch_vst, it_sos, it_bol, de_kst, de_sol, de_kis)}

    For each year in TAXB, compute the annuity tax amounts.
    The condition for each tax type is determined by checking the address at each
    TAXB entry's date, not a single year-start date.
    """
    taxa = _load_table(legacy_dir, 'TAXB')
    hold_map = {h['HD_POLNR'].strip(): h['HD_PERNR'].strip()
                for h in _load_table(legacy_dir, 'HOLD')}
    addr_by_person = defaultdict(list)
    for a in _load_table(legacy_dir, 'ADDR'):
        addr_by_person[a['AD_PERNR'].strip()].append(a)
    taxr = _load_table(legacy_dir, 'TAXR')

    # Group entries by (policy, year)
    entries_by_pol_year = defaultdict(dict)
    for ta in taxa:
        pol = ta['TB_POLNR'].strip()
        eff_dt = _parse_date(ta['TB_EFFDT'])
        if eff_dt is None:
            continue
        year = eff_dt.year
        tax_tp = ta['TB_TAXTP']
        if tax_tp not in entries_by_pol_year[(pol, year)]:
            entries_by_pol_year[(pol, year)][tax_tp] = []
        entries_by_pol_year[(pol, year)][tax_tp].append(ta)

    result = {}

    for (pol, year), type_entries in entries_by_pol_year.items():
        check_date = dt.date(year, 1, 1)
        per_nr = hold_map.get(pol)
        if per_nr is None:
            continue
        addresses = addr_by_person.get(per_nr, [])

        # Tax types present this year
        tax_types = set(type_entries.keys())

        # Annual (fund_value × rate) taxes
        ch_stp = Decimal('0')
        ch_vst = Decimal('0')
        it_bol = Decimal('0')
        it_sos = Decimal('0')

        # STP: stamp duty for CH policies
        if 'STP' in tax_types:
            country_stp = _country_at_date(addresses, dt.date(year, 12, 31))
            if country_stp == 'CH':
                fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
                fv = fv_raw / 100
                info = _tax_rate_for(taxr, 'STP', dt.date(year, 12, 31))
                if info:
                    ch_stp = cents(info[0] * fv)

        # VST: withholding tax for Swiss policies with specific canton
        if 'VST' in tax_types:
            # Check each VST entry's date for the country/canton
            for ta in type_entries['VST']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_vst = _country_at_date(addresses, ta_eff)
                if country_vst != 'CH':
                    continue
                # Get versioned address at this date for AD_TAXST
                best_addr = None
                best_vldf = None
                for addr in addresses:
                    ad_vl_df = _parse_date(addr.get('AD_VLDFR', ''))
                    ad_vl_to = _parse_date(addr.get('AD_VLDTO', ''))
                    if ad_vl_df and ad_vl_df <= ta_eff:
                        if ad_vl_to is None or ad_vl_to >= ta_eff:
                            if best_vldf is None or ad_vl_df > best_vldf:
                                best_addr = addr
                                best_vldf = ad_vl_df
                if best_addr and best_addr.get('AD_TAXST') == 'E':
                    # Swiss policy in canton E: apply VST on payout
                    fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
                    fv = fv_raw / 100
                    info = _tax_rate_for(taxr, 'VST', ta_eff)
                    if info:
                        rate, thrsh = info
                        base = fv - (thrsh / 100 if thrsh else Decimal('5000'))
                        ch_vst += max(Decimal('0'), rate * base)

        # SOS for Italian policies
        if 'SOS' in tax_types:
            fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
            fv = fv_raw / 100
            for ta in type_entries['SOS']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_sos = _country_at_date(addresses, ta_eff)
                if country_sos != 'IT':
                    continue
                info = _tax_rate_for(taxr, 'SOS', ta_eff)
                if info:
                    it_sos = cents(info[0] * fv)

        # BOL for Italian policies
        if 'BOL' in tax_types:
            fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
            fv = fv_raw / 100
            for ta in type_entries['BOL']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_bol = _country_at_date(addresses, ta_eff)
                if country_bol != 'IT':
                    continue
                bol_rate, _ = _tax_rate_for(taxr, 'BOL', ta_eff)
                if bol_rate is not None:
                    it_bol += cents(bol_rate * fv)

        # KST: German income tax on insurance gains
        de_kst = de_sol = de_kis = Decimal('0')
        if 'KST' in tax_types:
            # Check if any KST entries are for DE country
            kst_country_ok = False
            for ta in type_entries['KST']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_kst = _country_at_date(addresses, ta_eff)
                if country_kst == 'DE':
                    kst_country_ok = True
                    break
            if kst_country_ok:
                premiums_to_date = _total_premiums_up_to(pol, dt.date(year, 12, 31), legacy_dir)
                fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
                fv = fv_raw / 100
                gain = _fund_gain(premiums_to_date, fv, premiums_to_date)
                for ta in type_entries['KST']:
                    ta_eff = _parse_date(ta['TB_EFFDT'])
                    if ta_eff is None:
                        continue
                    info = _tax_rate_for(taxr, 'KST', ta_eff)
                    if info:
                        de_kst = cents(info[0] * gain)

        # SOL: surcharge on KST for German policies
        if 'SOL' in tax_types and de_kst:
            for ta in type_entries['SOL']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_sol = _country_at_date(addresses, ta_eff)
                if country_sol != 'DE':
                    continue
                info = _tax_rate_for(taxr, 'SOL', ta_eff)
                if info:
                    de_sol = cents(info[0] * de_kst)

        # KIS for German policies
        if 'KIS' in tax_types:
            for ta in type_entries['KIS']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                country_kis = _country_at_date(addresses, ta_eff)
                if country_kis != 'DE':
                    continue
                info = _tax_rate_for(taxr, 'KIS', ta_eff)
                if info:
                    pre_fund_v_raw, total_prem_raw = _fund_value_at(pol, ta_eff, legacy_dir)
                    pre_fund_v = pre_fund_v_raw / 100
                    total_prem = total_prem_raw / 100
                    gain = max(Decimal(0), pre_fund_v - total_prem)
                    de_kis = cents(info[0] * gain)

        if country == 'LU' and 'KIS' in tax_types:
            for ta in type_entries['KIS']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                info = _tax_rate_for(taxr, 'KIS', ta_eff)
                if info:
                    pre_fund_v_raw, total_prem_raw = _fund_value_at(pol, ta_eff, legacy_dir)
                    gain = max(Decimal(0), pre_fund_v_raw / 100 - total_prem_raw / 100)
                    de_kis = cents(info[0] * gain)

        if any(v != Decimal('0') for v in (ch_stp, ch_vst, de_kst, de_sol, de_kis, it_sos, it_bol)):
            result[(pol, year)] = (
                cents(ch_stp), cents(ch_vst), cents(it_sos), cents(it_bol),
                cents(de_kst), cents(de_sol), cents(de_kis),
            )

    return result

