            for ta in tax_types_by_sub['SOL']:
                ta_eff = _parse_date(ta['TB_EFFDT'])
                if ta_eff is None:
                    continue
                info = _tax_rate_for(taxr, 'SOL', ta_eff)
                if info and de_kst:
                    de_sol = cents(info[0] * de_kst)

        if 'KIS' in tax_types and country == 'DE':
            for ta in tax_types_by_sub['KIS']:
