        if ta_eff is None:
            continue
        country_vst = _country_at_date(addresses, ta_eff)
        if country_vst != 'CH':
            continue
        # Use fund_value at year-end or NRBOOK payout as base
        fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
        fv = fv_raw / 100
        info = _tax_rate_for(taxr, 'VST', ta_eff)
        if info:
            rate, thrsh = info
            threshold = thrsh / 100 if thrsh else Decimal('5000')
            base = fv - threshold
            if base <= 0:
                # Fund value below threshold: try NRBOOK payout as base
                # Sum up payouts for events in this policy that have VST entries
                for ta_vst in type_entries['VST']:
                    ta_vst_evt = int(ta_vst['TB_EVTNR'])
                    payout = payouts_annual.get((pol, ta_vst_evt), Decimal('0'))
                    if payout > threshold:
                        base = payout - threshold
                        break
                else:
                    continue  # No valid base, skip
            ch_vst += max(Decimal('0'), rate * base)

