if 'SOS' in tax_types:
    fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
    fv = fv_raw / 100
    it_sos = Decimal('0')
    for ta in type_entries['SOS']:
        ta_eff = _parse_date(ta['TB_EFFDT'])
        if ta_eff is None:
            continue
        country_sos = _country_at_date(addresses, ta_eff)
        if country_sos != 'IT':
            continue
        info = _tax_rate_for(taxr, 'SOS', ta_eff)
        if info:
            if fv >= _tax_threshold_for(taxr, 'SOS'):
                it_sos += info[0] * fv
            else:
                # Fund value too low: use NRBOOK payout as base
                ta_evt = int(ta['TB_EVTNR'])
                payout = payouts_annual.get((pol, ta_evt), Decimal('0'))
                if payout > 0:
                    it_sos += info[0] * payout
                else:
                    # No payout either: use fund_value anyway
                    it_sos += info[0] * fv

# BOL for Italian policies
if 'BOL' in tax_types:
    fv_raw = _fund_value_at_year(pol, year, legacy_dir)[0]
    fv = fv_raw / 100
    it_bol = Decimal('0')
    for ta in type_entries['BOL']:
        ta_eff = _parse_date(ta['TB_EFFDT'])
        if ta_eff is None:
            continue
        country_bol = _country_at_date(addresses, ta_eff)
        if country_bol != 'IT':
            continue
        bol_rate, _ = _tax_rate_for(taxr, 'BOL', ta_eff)
        if bol_rate is not None:
            if fv >= 0:
                it_bol += cents(bol_rate * fv)
            else:
                # Negative fund value: use payout as base
                ta_evt = int(ta['TB_EVTNR'])
                payout = payouts_annual.get((pol, ta_evt), Decimal('0'))
                it_bol += cents(bol_rate * payout)

