            for h in hold:
                if h['HD_POLNR'].strip() == pol:
                    per_nr = h['HD_PERNR']
            if per_nr:
                for a in csv.DictReader(open('legacy/NRADDR.csv'), delimiter=';'):
                    if a[\"AD_PERNR\"].strip() == per_nr:
                        print(f'  addr: {a[\"AD_VLDFR\"][:4]} -> {a[\"AD_VLDTO\"][:4] or \"99\"}  CNTRY={a[\"AD_CNTRY\"]}')
            # Check TAXB entries
            for r in csv.DictReader(open('legacy/NRTAXB.csv'), delimiter=';'):
                if r['TB_POLNR'].strip() == pol:
                    eff = r['TB_EFFDT']
                    if eff and eff[:4] == str(year):
                        print(f'  TAXB: {r[\"TB_TAXTP\"]} eff={eff}')
    else:
        print(f'{key}: NOT FOUND in result')
print()
